begin;
    with j as (select * from jsonb_to_recordset($law7v015$[{"code_id":"GK_RF_2","article_number":"685","version_date":"1994-11-30","article_text":"1. По договору поднайма жилого помещения наниматель с согласия наймодателя передает на срок часть или все нанятое им помещение в пользование поднанимателю. Поднаниматель не приобретает самостоятельного права пользования жилым помещением. Ответственным перед наймодателем по договору найма жилого помещения остается наниматель.\n\n2. Договор поднайма жилого пом\n\nещения может быть заключен при условии соблюдения требований законодательства о норме общей площади жилого помещения на одного человека. (В редакции Федерального закона от 29.12.2004 № 189-ФЗ)\n\n3. Договор поднайма жилого помещения является возмездным.\n\n4. Срок договора поднайма жилого помещения не может превышать срока договора найма жилого помещения.\n\n5. При досрочном прекращении договора найма жилого помещения одновременно с ним прекращается договор поднайма жилого помещения.\n\n6. На договор поднайма жилого помещения не распространяются правила о преимущественном праве на заключение договора на новый срок.","article_title":"Статья 685. Поднаем жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4aefcc5ffd69a23a6cbe9fdbacbe3f79b5e5a63fd4cd7408e1a2ef04464b4ee9"},{"code_id":"GK_RF_2","article_number":"686","version_date":"1994-11-30","article_text":"1. По требованию нанимателя и других граждан, постоянно с ним проживающих, и с согласия наймодателя наниматель в договоре найма жилого помещения может быть заменен одним из совершеннолетних граждан, постоянно проживающих с нанимателем.\n\n2. В случае смерти нанимателя или его выбытия из жилого помещения договор продолжает действовать на тех же условиях, а нанимателем становится один из граждан, постоянно проживающих с прежним нанимателем, по общему согласию между ними. Если такое согласие не достигнуто, все граждане, постоянно проживающие в жилом помещении, становятся сонанимателями.","article_title":"Статья 686. Замена нанимателя в договоре найма жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f496751f2741559630e26c784804069f5519ba5241c657dc76052cfff36d7dfe"},{"code_id":"GK_RF_2","article_number":"687","version_date":"1994-11-30","article_text":"1. Наниматель жилого помещения вправе с согласия других граждан, постоянно проживающих с ним, в любое время расторгнуть договор найма с письменным предупреждением наймодателя за три месяца.\n\n2. Договор найма жилого помещения может быть расторгнут в судебном порядке по требованию наймодателя в случаях:\n\nневнесения нанимателем платы за жилое помещение за шесть месяцев, если договором не установлен более длительный срок, а при краткосрочном найме в случае невнесения платы более двух раз по истечении установленного договором срока платежа;\n\nразрушения или порчи жилого помещения нанимателем или другими гражданами, за действия которых он отвечает.\n\nПо решению суда нанимателю может быть предоставлен срок не более года для устранения им нарушений, послуживших основанием для расторжения договора найма жилого помещения. Если в течение определенного судом срока наниматель не устранит допущенных нарушений или не примет всех необходимых мер для их устранения, суд по повторному обращению наймодателя принимает решение о расторжении договора найма жилого помещения. При этом по просьбе нанимателя суд в решении о расторжении договора может отсрочить исполнение решения на срок не более года.\n\n3. Договор найма жилого помещения может быть расторгнут в судебном порядке по требованию любой из сторон в договоре:\n\nесли помещение перестает быть пригодным для постоянного проживания, а также в случае его аварийного состояния;\n\nв других случаях, предусмотренных жилищным законодательством.\n\n4. Если наниматель жилого помещения или другие граждане, за действия которых он отвечает, используют жилое помещение не по назначению либо систематически нарушают права и интересы соседей, наймодатель может предупредить нанимателя о необходимости устранения нарушения.\n\nЕсли наниматель или другие граждане, за действия которых он отвечает, после предупреждения продолжают использовать жилое помещение не по назначению или нарушать права и интересы соседей, наймодатель вправе в судебном порядке расторгнуть договор найма жилого помещения. В этом случае применяются правила, предусмотренные абзацем четвертым пункта 2 настоящей статьи.","article_title":"Статья 687. Расторжение договора найма жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d7eb715936932db23755a65039c32d2d05b079ffacde35e9d2d48b94732e767e"},{"code_id":"GK_RF_2","article_number":"688","version_date":"1994-11-30","article_text":"В случае расторжения договора найма жилого помещения наниматель и другие граждане, проживающие в жилом помещении к моменту расторжения договора, подлежат выселению из жилого помещения на основании решения суда.","article_title":"Статья 688. Последствия расторжения договора найма жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"45ca8371316ada3395a668ddc0126c5f452ca928a53159d88bfa1de2f7699411"},{"code_id":"GK_RF_2","article_number":"689","version_date":"1994-11-30","article_text":"1. По договору безвозмездного пользования (договору ссуды) одна сторона (ссудодатель) обязуется передать или передает вещь в безвозмездное временное пользование другой стороне (ссудополучателю), а последняя обязуется вернуть ту же вещь в том состоянии, в каком она ее получила, с учетом нормального износа или в состоянии, обусловленном договором.\n\n2. К договору безвозмездного пользования соответственно применяются правила, предусмотренные статьей 607, пунктом 1 и абзацем первым пункта 2 статьи 610, пунктами 1 и 3 статьи 615, пунктом 2 статьи 621, пунктами 1 и 3 статьи 623 настоящего Кодекса.","article_title":"Статья 689. Договор безвозмездного пользования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"01451094f24a4e3626ab97257c62f7e9507925ddb2b2e21e87fa032cd32c1395"},{"code_id":"GK_RF_2","article_number":"690","version_date":"1994-11-30","article_text":"1. Право передачи вещи в безвозмездное пользование принадлежит ее собственнику и иным лицам, управомоченным на то законом или собственником.\n\n2. Коммерческая организация не вправе передавать имущество в безвозмездное пользование лицу, являющемуся ее учредителем, участником, руководителем, членом ее органов управления или контроля.","article_title":"Статья 690. Ссудодатель","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"355735012cbca138242c70ba470dcb11cae001c624f19a6c8ff0744b59c894ab"},{"code_id":"GK_RF_2","article_number":"691","version_date":"1994-11-30","article_text":"1. Ссудодатель обязан предоставить вещь в состоянии, соответствующем условиям договора безвозмездного пользования и ее назначению.\n\n2. Вещь предоставляется в безвозмездное пользование со всеми ее принадлежностями и относящимися к ней документами (инструкцией по использованию, техническим паспортом и т.п.), если иное не предусмотрено договором.\n\nЕсли такие принадлежности и документы переданы не были, однако без них вещь не может быть использована по назначению либо ее использование в значительной степени утрачивает ценность для ссудополучателя, последний вправе потребовать предоставления ему таких принадлежностей и документов либо расторжения договора и возмещения понесенного им реального ущерба.","article_title":"Статья 691. Предоставление вещи в безвозмездное пользование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7142ef59ac247a47147477536f4812d1019039f6f356ddcc63cf8e49043ec9d6"},{"code_id":"GK_RF_2","article_number":"692","version_date":"1994-11-30","article_text":"Если ссудодатель не передает вещь ссудополучателю, последний вправе потребовать расторжения договора безвозмездного пользования и возмещения понесенного им реального ущерба.","article_title":"Статья 692. Последствия непредоставления вещи в безвозмездное пользование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bd7eff78d5a0ce6c7f43dd9850bb70f23ce263dede2ad58e69db3e821b31a2c9"},{"code_id":"GK_RF_2","article_number":"693","version_date":"1994-11-30","article_text":"1. Ссудодатель отвечает за недостатки вещи, которые он умышленно или по грубой неосторожности не оговорил при заключении договора безвозмездного пользования.\n\nПри обнаружении таких недостатков ссудополучатель вправе по своему выбору потребовать от ссудодателя безвозмездного устранения недостатков вещи или возмещения своих расходов на устранение недостатков вещи либо досрочного расторжения договора и возмещения понесенного им реального ущерба.\n\n2. Ссудодатель, извещенный о требованиях ссудополучателя или о его намерении устранить недостатки вещи за счет ссудодателя, может без промедления произвести замену неисправной вещи другой аналогичной вещью, находящейся в надлежащем состоянии.\n\n3. Ссудодатель не отвечает за недостатки вещи, которые были им оговорены при заключении договора, либо были заранее известны ссудополучателю, либо должны были быть обнаружены ссудополучателем во время осмотра вещи или проверки ее исправности при заключении договора или при передаче вещи.","article_title":"Статья 693. Ответственность за недостатки вещи, переданной в безвозмездное пользование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8d766c25a1a03a1e9c7eb107a830e1c83247cd41e6657c4d800ff590615021d5"},{"code_id":"GK_RF_2","article_number":"694","version_date":"1994-11-30","article_text":"Передача вещи в безвозмездное пользование не является основанием для изменения или прекращения прав третьих лиц на эту вещь.\n\nПри заключении договора безвозмездного пользования ссудодатель обязан предупредить ссудополучателя о всех правах третьих лиц на эту вещь (сервитуте, праве залога и т.п.). Неисполнение этой обязанности дает ссудополучателю право требовать расторжения договора и возмещения понесенного им реального ущерба.","article_title":"Статья 694. Права третьих лиц на вещь, передаваемую в безвозмездное пользование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"633e0408a72af10d65b381bbc0f1dd5c5bab385f2c3b7810bae7b2cabbbb8bba"},{"code_id":"GK_RF_2","article_number":"695","version_date":"1994-11-30","article_text":"Ссудополучатель обязан поддерживать вещь, полученную в безвозмездное пользование, в исправном состоянии, включая осуществление текущего и капитального ремонта, и нести все расходы на ее содержание, если иное не предусмотрено договором безвозмездного пользования.","article_title":"Статья 695. Обязанности ссудополучателя по содержанию вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4379e7acf1c9728b5839fc2a1c159a4ced2414a05d0b1c823b242748ba30db66"},{"code_id":"GK_RF_2","article_number":"696","version_date":"1994-11-30","article_text":"Ссудополучатель несет риск случайной гибели или случайного повреждения полученной в безвозмездное пользование вещи, если вещь погибла или была испорчена в связи с тем, что он использовал ее не в соответствии с договором безвозмездного пользования или назначением вещи либо передал ее третьему лицу без согласия ссудодателя. Ссудополучатель несет также риск случайной гибели или случайного повреждения вещи, если с учетом фактических обстоятельств мог предотвратить ее гибель или порчу, пожертвовав своей вещью, но предпочел сохранить свою вещь.","article_title":"Статья 696. Риск случайной гибели или случайного повреждения вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"456c4c084e04f734d295a98b07251b7c4a5346a133f1be454d3464d6c1b77cb0"},{"code_id":"GK_RF_2","article_number":"697","version_date":"1994-11-30","article_text":"Ссудодатель отвечает за вред, причиненный третьему лицу в результате использования вещи, если не докажет, что вред причинен вследствие умысла или грубой неосторожности ссудополучателя или лица, у которого эта вещь оказалась с согласия ссудодателя.","article_title":"Статья 697. Ответственность за вред, причиненный третьему лицу в результате использования вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f8d1459d7530590c6ac8dc8cf060c2bf24e6a7d842ca63886d1403d9fcfdc0f3"},{"code_id":"GK_RF_2","article_number":"698","version_date":"1994-11-30","article_text":"1. Ссудодатель вправе потребовать досрочного расторжения договора безвозмездного пользования в случаях, когда ссудополучатель:\n\nиспользует вещь не в соответствии с договором или назначением вещи;\n\nне выполняет обязанностей по поддержанию вещи в исправном состоянии или ее содержанию;\n\nсущественно ухудшает состояние вещи;\n\nбез согласия ссудодателя передал вещь третьему лицу.\n\n2. Ссудополучатель вправе требовать досрочного расторжения договора безвозмездного пользования:\n\nпри обнаружении недостатков, делающих нормальное использование вещи невозможным или обременительным, о наличии которых он не знал и не мог знать в момент заключения договора;\n\nесли вещь в силу обстоятельств, за которые он не отвечает, окажется в состоянии, непригодном для использования;\n\nесли при заключении договора ссудодатель не предупредил его о правах третьих лиц на передаваемую вещь;\n\nпри неисполнении ссудодателем обязанности передать вещь либо ее принадлежности и относящиеся к ней документы.","article_title":"Статья 698. Досрочное расторжение договора безвозмездного пользования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e186610abab44fc30f1cd2dab341052b87098bc4ff6a5772095f946b8d4b60d9"},{"code_id":"GK_RF_2","article_number":"699","version_date":"1994-11-30","article_text":"1. Каждая из сторон вправе во всякое время отказаться от договора безвозмездного пользования, заключенного без указания срока, известив об этом другую сторону за один месяц, если договором не предусмотрен иной срок извещения.\n\n2. Если иное не предусмотрено договором, ссудополучатель вправе во всякое время отказаться от договора, заключенного с указанием срока, в порядке, предусмотренном пунктом 1 настоящей статьи.","article_title":"Статья 699. Отказ от договора безвозмездного пользования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a17e3c7044c6324523fbefadae63211f9bc0986defc01fae715c93ab03b2aecf"},{"code_id":"GK_RF_2","article_number":"700","version_date":"1994-11-30","article_text":"1. Ссудодатель вправе произвести отчуждение вещи или передать ее в возмездное пользование третьему лицу. При этом к новому собственнику или пользователю переходят права по ранее заключенному договору безвозмездного пользования, а его права в отношении вещи обременяются правами ссудополучателя.\n\n2. В случае смерти гражданина-ссудодателя либо реорганизации или ликвидации юридического лица - ссудодателя права и обязанности ссудодателя по договору безвозмездного пользования переходят к наследнику (правопреемнику) или к другому лицу, к которому перешло право собственности на вещь или иное право, на основании которого вещь была передана в безвозмездное пользование.\n\nВ случае реорганизации юридического лица - ссудополучателя его права и обязанности по договору переходят к юридическому лицу, являющемуся его правопреемником, если иное не предусмотрено договором.","article_title":"Статья 700. Изменение сторон в договоре безвозмездного пользования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"99bfa6cf33b3c7711f2fd3e9ea7e3607277778c9dd2b0ff9075a3c8baee87a00"},{"code_id":"GK_RF_2","article_number":"701","version_date":"1994-11-30","article_text":"Договор безвозмездного пользования прекращается в случае смерти гражданина-ссудополучателя или ликвидации юридического лица - ссудополучателя, если иное не предусмотрено договором.","article_title":"Статья 701. Прекращение договора безвозмездного пользования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"af5bbb16119f98997d1e6c1cfbc1767ce1f1c3dd7d28a0ec4d5f18c5cb073ce5"},{"code_id":"GK_RF_2","article_number":"702","version_date":"1994-11-30","article_text":"1. По договору подряда одна сторона (подрядчик) обязуется выполнить по заданию другой стороны (заказчика) определенную работу и сдать ее результат заказчику, а заказчик обязуется принять результат работы и оплатить его.\n\n2. К отдельным видам договора подряда (бытовой подряд, строительный подряд, подряд на выполнение проектных и изыскательских работ, подрядные работы для государственных нужд) положения, предусмотренные настоящим параграфом, применяются, если иное не установлено правилами настоящего Кодекса об этих видах договоров.","article_title":"Статья 702. Договор подряда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8a8a6ddec695963f78a95d3586623919f014f15af204c88a89ec7431e754bd9a"},{"code_id":"GK_RF_2","article_number":"703","version_date":"1994-11-30","article_text":"1. Договор подряда заключается на изготовление или переработку (обработку) вещи либо на выполнение другой работы с передачей ее результата заказчику.\n\n2. По договору подряда, заключенному на изготовление вещи, подрядчик передает права на нее заказчику.\n\n3. Если иное не предусмотрено договором, подрядчик самостоятельно определяет способы выполнения задания заказчика.","article_title":"Статья 703. Работы, выполняемые по договору подряда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"03e19830d8c42cf1a6de0a89232d271ab09f7c2b1fc2eec1ab35d2f1a454e4dd"},{"code_id":"GK_RF_2","article_number":"704","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором подряда, работа выполняется иждивением подрядчика - из его материалов, его силами и средствами.\n\n2. Подрядчик несет ответственность за ненадлежащее качество предоставленных им материалов и оборудования, а также за предоставление материалов и оборудования, обремененных правами третьих лиц.","article_title":"Статья 704. Выполнение работы иждивением подрядчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c0bd77108fa5d5a21c8f0caae4c5601cc73f66aad9c35c25030af72e11127541"},{"code_id":"GK_RF_2","article_number":"705","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено настоящим Кодексом, иными законами или договором подряда:\n\nриск случайной гибели или случайного повреждения материалов, оборудования, переданной для переработки (обработки) вещи или иного используемого для исполнения договора имущества несет предоставившая их сторона;\n\nриск случайной гибели или случайного повреждения результата выполненной работы до ее приемки заказчиком несет подрядчик.\n\n2. При просрочке передачи или приемки результата работы риски, предусмотренные в пункте 1 настоящей статьи, несет сторона, допустившая просрочку.","article_title":"Статья 705. Распределение рисков между сторонами","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0aa1f64e34fb2dde8a080dd758f02ee3f35665f3188df81870618d6788228462"},{"code_id":"GK_RF_2","article_number":"706","version_date":"1994-11-30","article_text":"1. Если из закона или договора подряда не вытекает обязанность подрядчика выполнить предусмотренную в договоре работу лично, подрядчик вправе привлечь к исполнению своих обязательств других лиц (субподрядчиков). В этом случае подрядчик выступает в роли генерального подрядчика.\n\n2. Подрядчик, который привлек к исполнению договора подряда субподрядчика в нарушение положений пункта 1 настоящей статьи или договора, несет перед заказчиком ответственность за убытки, причиненные участием субподрядчика в исполнении договора.\n\n3. Генеральный подрядчик несет перед заказчиком ответственность за последствия неисполнения или ненадлежащего исполнения обязательств субподрядчиком в соответствии с правилами пункта 1 статьи 313 и статьи 403 настоящего Кодекса, а перед субподрядчиком - ответственность за неисполнение или ненадлежащее исполнение заказчиком обязательств по договору подряда.\n\nЕсли иное не предусмотрено законом или договором, заказчик и субподрядчик не вправе предъявлять друг другу требования, связанные с нарушением договоров, заключенных каждым из них с генеральным подрядчиком.\n\n4. С согласия генерального подрядчика заказчик вправе заключить договоры на выполнение отдельных работ с другими лицами. В этом случае указанные лица несут ответственность за неисполнение или ненадлежащее исполнение работы непосредственно перед заказчиком.","article_title":"Статья 706. Генеральный подрядчик и субподрядчик","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0184158fdf213d1d8f1a9c8cd57d3507c9443151ec277c0e2cb456505e3ba72f"},{"code_id":"GK_RF_2","article_number":"707","version_date":"1994-11-30","article_text":"1. Если на стороне подрядчика выступают одновременно два лица или более, при неделимости предмета обязательства они признаются по отношению к заказчику солидарными должниками и соответственно солидарными кредиторами.\n\n2. При делимости предмета обязательства, а также в других случаях, предусмотренных законом, иными правовыми актами или договором, каждое из указанных в пункте 1 настоящей статьи лиц приобретает права и несет обязанности по отношению к заказчику в пределах своей доли (статья 321).","article_title":"Статья 707. Участие в исполнении работы нескольких лиц","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0185be2b432c72dd0c3f8e77f71be758f792848ae00203bc7d9e41b0e030a865"},{"code_id":"GK_RF_2","article_number":"708","version_date":"1994-11-30","article_text":"1. В договоре подряда указываются начальный и конечный сроки выполнения работы. По согласованию между сторонами в договоре могут быть предусмотрены также сроки завершения отдельных этапов работы (промежуточные сроки).\n\nЕсли иное не установлено законом, иными правовыми актами или не предусмотрено договором, подрядчик несет ответственность за нарушение как начального и конечного, так и промежуточных сроков выполнения работы.\n\n2. Указанные в договоре подряда начальный, конечный и промежуточные сроки выполнения работы могут быть изменены в случаях и в порядке, предусмотренных договором.","article_title":"Статья 708. Сроки выполнения работы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0d61edbc5fc9ed001d2d4054f28d7ad9088e053ece8c901028fac0e437eca8eb"},{"code_id":"GK_RF_2","article_number":"709","version_date":"1994-11-30","article_text":"1. В договоре подряда указываются цена подлежащей выполнению работы или способы ее определения. При отсутствии в договоре таких указаний цена определяется в соответствии с пунктом 3 статьи 424 настоящего Кодекса.\n\n2. Цена в договоре подряда включает компенсацию издержек подрядчика и причитающееся ему вознаграждение.\n\n3. Цена работы может быть определена путем составления сметы.\n\nВ случае, когда работа выполняется в соответствии со сметой, составленной подрядчиком, смета приобретает силу и становится частью договора подряда с момента подтверждения ее заказчиком.\n\n4. Цена работы (смета) может быть приблизительной или твердой. При отсутствии других указаний в договоре подряда цена работы считается твердой.\n\n5. Если возникла необходимость в проведении дополнительных работ и по этой причине в существенном превышении определенной приблизительно цены работы, подрядчик обязан своевременно предупредить об этом заказчика. Заказчик, не согласившийся на превышение указанной в договоре подряда цены работы, вправе отказаться от договора. В этом случае подрядчик может требовать от заказчика уплаты ему цены за выполненную часть работы.\n\nПодрядчик, своевременно не предупредивший заказчика о необходимости превышения указанной в договоре цены работы, обязан выполнить договор, сохраняя право на оплату работы по цене, определенной в договоре.\n\n6. Подрядчик не вправе требовать увеличения твердой цены, а заказчик ее уменьшения, в том числе в случае, когда в момент заключения договора подряда исключалась возможность предусмотреть полный объем подлежащих выполнению работ или необходимых для этого расходов.\n\nПри существенном возрастании стоимости материалов и оборудования, предоставленных подрядчиком, а также оказываемых ему третьими лицами услуг, которые нельзя было предусмотреть при заключении договора, подрядчик имеет право требовать увеличения установленной цены, а при отказе заказчика выполнить это требование - расторжения договора в соответствии со статьей 451 настоящего Кодекса.","article_title":"Статья 709. Цена работы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8e0c9b853827c5396c88f0a14a72ca43e548a7ef78e02ba3e748988ffdffee2c"},{"code_id":"GK_RF_2","article_number":"710","version_date":"1994-11-30","article_text":"1. В случаях, когда фактические расходы подрядчика оказались меньше тех, которые учитывались при определении цены работы, подрядчик сохраняет право на оплату работ по цене, предусмотренной договором подряда, если заказчик не докажет, что полученная подрядчиком экономия повлияла на качество выполненных работ.\n\n2. В договоре подряда может быть предусмотрено распределение полученной подрядчиком экономии между сторонами.","article_title":"Статья 710. Экономия подрядчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0fc698abd2624c9240921126cb28aed80ca5b1586418f12b43a204a3ec8b8f19"},{"code_id":"GK_RF_2","article_number":"711","version_date":"1994-11-30","article_text":"1. Если договором п\n\nодряда не предусмотрена предварительная оплата выполненной работы или отдельных ее этапов, заказчик обязан уплатить подрядчику обусловленную цену после окончательной сдачи результатов работы при условии, что работа выполнена надлежащим образом и в согласованный срок, либо с согласия заказчика досрочно.\n\n2. Подрядчик вправе требовать выплаты ему аванса либо задатка только в случаях и в размере, указанных в законе или договоре подряда.","article_title":"Статья 711. Порядок оплаты работы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f7ee4be35b9f87cb8130e2fbb716fd44c1f33f619d425d44c8165f7f1bd9cb1a"},{"code_id":"GK_RF_2","article_number":"712","version_date":"1994-11-30","article_text":"При неисполнении заказчиком обязанности уплатить установленную цену либо иную сумму, причитающуюся подрядчику в связи с выполнением договора подряда, подрядчик имеет право на удержание в соответствии со статьями 359 и 360 настоящего Кодекса результата работ, а также принадлежащих заказчику оборудования, переданной для переработки (обработки) вещи, остатка неиспользованного материала и другого оказавшегося у него имущества заказчика до уплаты заказчиком соответствующих сумм.","article_title":"Статья 712. Право подрядчика на удержание","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5a4cc1cd64662f355295ab9ea8c73ca4e76526c38754f3d89ed357d12e7f27fe"},{"code_id":"GK_RF_2","article_number":"713","version_date":"1994-11-30","article_text":"1. Подрядчик обязан использовать предоставленный заказчиком материал экономно и расчетливо, после окончания работы представить заказчику отчет об израсходовании материала, а также возвратить его остаток либо с согласия заказчика уменьшить цену работы с учетом стоимости остающегося у подрядчика неиспользованного материала.\n\n2. Если результат работы не был достигнут либо достигнутый результат оказался с недостатками, которые делают его не пригодным для предусмотренного в договоре подряда использования, а при отсутствии в договоре соответствующего условия не пригодным для обычного использования, по причинам, вызванным недостатками предоставленного заказчиком материала, подрядчик вправе потребовать оплаты выполненной им работы.\n\n3. Подрядчик может осуществить право, указанное в пункте 2 настоящей статьи, в случае, если докажет, что недостатки материала не могли быть обнаружены при надлежащей приемке подрядчиком этого материала.","article_title":"Статья 713. Выполнение работы с использованием материала заказчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9e62e68760d424af9249575d4f3dc2a39b7054dccb5567f8f8697b559b7edc98"},{"code_id":"GK_RF_2","article_number":"714","version_date":"1994-11-30","article_text":"Подрядчик несет ответственность за несохранность предоставленных заказчиком материала, оборудования, переданной для переработки (обработки) вещи или иного имущества, оказавшегося во владении подрядчика в связи с исполнением договора подряда.","article_title":"Статья 714. Ответственность подрядчика за несохранность предоставленного заказчиком имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bdf9f9ef72c4860ac0dbfc25345af99ce0914fe58549f3944e44b2d382d98604"},{"code_id":"GK_RF_2","article_number":"715","version_date":"1994-11-30","article_text":"1. Заказчик вправе во всякое время проверять ход и качество работы, выполняемой подрядчиком, не вмешиваясь в его деятельность.\n\n2. Если подрядчик не приступает своевременно к исполнению договора подряда или выполняет работу настолько медленно, что окончание ее к сроку становится явно невозможным, заказчик вправе отказаться от исполнения договора и потребовать возмещения убытков.\n\n3. Если во время выполнения работы станет очевидным, что она не будет выполнена надлежащим образом, заказчик вправе назначить подрядчику разумный срок для устранения недостатков и при неисполнении подрядчиком в назначенный срок этого требования отказаться от договора подряда либо поручить исправление работ другому лицу за счет подрядчика, а также потребовать возмещения убытков.","article_title":"Статья 715. Права заказчика во время выполнения работы подрядчиком","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ba7776cf84f1a7ff0dcfe9d4c5a7dfb887dce32cd738e61f59c9b2f162d5be51"},{"code_id":"GK_RF_2","article_number":"716","version_date":"1994-11-30","article_text":"1. Подрядчик обязан немедленно предупредить заказчика и до получения от него указаний приостановить работу при обнаружении:\n\nнепригодности или недоброкачественности предоставленных заказчиком материала, оборудования, технической документации или переданной для переработки (обработки) вещи;\n\nвозможных неблагоприятных для заказчика последствий выполнения его указаний о способе исполнения работы;\n\nиных не зависящих от подрядчика обстоятельств, которые грозят годности или прочности результатов выполняемой работы либо создают невозможность ее завершения в срок.\n\n2. Подрядчик, не предупредивший заказчика об обстоятельствах, указанных в пункте 1 настоящей статьи, либо продолживший работу, не дожидаясь истечения указанного в договоре срока, а при его отсутствии разумного срока для ответа на предупреждение или несмотря на своевременное указание заказчика о прекращении работы, не вправе при предъявлении к нему или им к заказчику соответствующих требований ссылаться на указанные обстоятельства.\n\n3. Если заказчик, несмотря на своевременное и обоснованное предупреждение со стороны подрядчика об обстоятельствах, указанных в пункте 1 настоящей статьи, в разумный срок не заменит непригодные или недоброкачественные материал, оборудование, техническую документацию или переданную для переработки (обработки) вещь, не изменит указаний о способе выполнения работы или не примет других необходимых мер для устранения обстоятельств, грозящих ее годности, подрядчик вправе отказаться от исполнения договора подряда и потребовать возмещения причиненных его прекращением убытков.","article_title":"Статья 716. Обстоятельства, о которых подрядчик обязан предупредить заказчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6ae0d5eac2790de5f1af57843c1bcedfb841c5fb46cb817d5c2f592faff944db"},{"code_id":"GK_RF_2","article_number":"717","version_date":"1994-11-30","article_text":"Если иное не предусмотрено договором подряда, заказчик может в любое время до сдачи ему результата работы отказаться от исполнения договора, уплатив подрядчику часть установленной цены пропорционально части работы, выполненной до получения извещения об отказе заказчика от исполнения договора. Заказчик также обязан возместить подрядчику убытки, причиненные прекращением договора подряда, в пределах разницы между ценой, определенной за всю работу, и частью цены, выплаченной за выполненную работу.","article_title":"Статья 717. Отказ заказчика от исполнения договора подряда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a1aaff1d56175c9e1457a695432ec3096cd22e461ca1c348b33d37dc372de1b2"},{"code_id":"GK_RF_2","article_number":"718","version_date":"1994-11-30","article_text":"1. Заказчик обязан в случаях, в объеме и в порядке, предусмотренных договором подряда, оказывать подрядчику содействие в выполнении работы.\n\nПри неисполнении заказчиком этой обязанности подрядчик вправе требовать возмещения причиненных убытков, включая дополнительные издержки, вызванные простоем, либо перенесения сроков исполнения работы, либо увеличения указанной в договоре цены работы.\n\n2. В случаях, когда исполнение работы по договору подряда стало невозможным вследствие действий или упущений заказчика, подрядчик сохраняет право на уплату ему указанной в договоре цены с учетом выполненной части работы.","article_title":"Статья 718. Содействие заказчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7d2e7b8ca86e57ffc6a37fe4edef973930705054485e7e2109be4c265d9a0f81"},{"code_id":"GK_RF_2","article_number":"719","version_date":"1994-11-30","article_text":"1. Подрядчик вправе не приступать к работе, а начатую работу приостановить в случаях, когда нарушение заказчиком своих обязанностей по договору подряда, в частности непредоставление материала, оборудования, технической документации или подлежащей переработке (обработке) вещи, препятствует исполнению договора подрядчиком, а также при наличии обстоятельств, очевидно свидетельствующих о том, что исполнение указанных обязанностей не будет произведено в установленный срок (статья 328).\n\n2. Если иное не предусмотрено договором подряда, подрядчик при наличии обстоятельств, указанных в пункте 1 настоящей статьи, вправе отказаться от исполнения договора и потребовать возмещения убытков.","article_title":"Статья 719. Неисполнение заказчиком встречных обязанностей по договору подряда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"df010e4140a3e080f32f6dc60a285a4fc8af211d0d310680752e23f146ca7a36"},{"code_id":"GK_RF_2","article_number":"720","version_date":"1994-11-30","article_text":"1. Заказчик обязан в сроки и в порядке, которые предусмотрены договором подряда, с участием подрядчика осмотреть и принять выполненную работу (ее результат), а при обнаружении отступлений от договора, ухудшающих результат работы, или иных недостатков в работе немедленно заявить об этом подрядчику.\n\n2. Заказчик, обнаруживший недостатки в работе при ее приемке, вправе ссылаться на них в случаях, если в акте либо в ином документе, удостоверяющем приемку, были оговорены эти недостатки либо возможность последующего предъявления требования об их устранении.\n\n3. Если иное не предусмотрено договором подряда, заказчик, принявший работу без проверки, лишается права ссылаться на недостатки работы, которые могли быть установлены при обычном способе ее приемки (явные недостатки).\n\n4. Заказчик, обнаруживший после приемки работы отступления в ней от договора подряда или иные недостатки, которые не могли быть установлены при обычном способе приемки (скрытые недостатки), в том числе такие, которые были умышленно скрыты подрядчиком, обязан известить об этом подрядчика в разумный срок по их обнаружении.\n\n5. При возникновении между заказчиком и подрядчиком спора по поводу недостатков выполненной работы или их причин по требованию любой из сторон должна быть назначена экспертиза. Расходы на экспертизу несет подрядчик, за исключением случаев, когда экспертизой установлено отсутствие нарушений подрядчиком договора подряда или причинной связи между действиями подрядчика и обнаруженными недостатками. В указанных случаях расходы на экспертизу несет сторона, потребовавшая назначения экспертизы, а если она назначена по соглашению между сторонами, обе стороны поровну.\n\n6. Если иное не предусмотрено договором подряда, при уклонении заказчика от принятия выполненной работы подрядчик вправе по истечении месяца со дня, когда согласно договору результат работы должен был быть передан заказчику, и при условии последующего двукратного предупреждения заказчика продать результат работы, а вырученную сумму, за вычетом всех причитающихся подрядчику платежей, внести на имя заказчика в депозит в порядке, предусмотренном статьей 327 настоящего Кодекса.\n\n7. Если уклонение заказчика от принятия выполненной работы повлекло за собой просрочку в сдаче работы, риск случайной гибели изготовленной (переработанной или обработанной) вещи признается перешедшим к заказчику в момент, когда передача вещи должна была состояться.","article_title":"Статья 720. Приемка заказчиком работы, выполненной подрядчиком","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7e98450342904d4284047f66512d651ed3f6f8258c2f220888c7f6e28238cf14"},{"code_id":"GK_RF_2","article_number":"721","version_date":"1994-11-30","article_text":"1. Качество выполненной подрядчиком работы должно соответствовать условиям договора подряда, а при отсутствии или неполноте условий договора требованиям, обычно предъявляемым к работам соответствующего рода. Если иное не предусмотрено законом, иными правовыми актами или договором, результат выполненной работы должен в момент передачи заказчику обладать свойствами, указанными в договоре или определенными обычно предъявляемыми требованиями, и в пределах разумного срока быть пригодным для установленного договором использования, а если такое использование договором не предусмотрено, для обычного использования результата работы такого рода.\n\n2. Если законом, иными правовыми актами или в установленном ими порядке предусмотрены обязательные требования к работе, выполняемой по договору подряда, подрядчик, действующий в качестве предпринимателя, обязан выполнять работу, соблюдая эти обязательные требования.\n\nПодрядчик может принять на себя по договору обязанность выполнить работу, отвечающую требованиям к качеству, более высоким по сравнению с установленными обязательными для сторон требованиями.","article_title":"Статья 721. Качество работы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ce804ae6270631f8bfd37f6c61d48b651e7363d966cb8dd7779de86b19d95647"},{"code_id":"GK_RF_2","article_number":"722","version_date":"1994-11-30","article_text":"1. В случае, когда законом, иным правовым актом, договором подряда или обычаями делового оборота предусмотрен для результата работы гарантийный срок, результат работы должен в течение всего гарантийного срока соответствовать условиям договора о качестве (пункт 1 статьи 721).\n\n2. Гарантия качества результата работы, если иное не предусмотрено договором подряда, распространяется на все, составляющее результат работы.","article_title":"Статья 722. Гарантия качества работы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3583121601c74bd63d81d40fe24acb59536a868cdab7337d7dde8be32328014f"},{"code_id":"GK_RF_2","article_number":"723","version_date":"1994-11-30","article_text":"1. В случаях, когда работа выполнена подрядчиком с отступлениями от договора подряда, ухудшившими результат работы, или с иными недостатками, которые делают его не пригодным для предусмотренного в договоре использования либо при отсутствии в договоре соответствующего условия непригодности для обычного использования, заказчик вправе, если иное не установлено законом или договором, по своему выбору потребовать от подрядчика:\n\nбезвозмездного устранения недостатков в разумный срок;\n\nсоразмерного уменьшения установленной за работу цены;\n\nвозмещения своих расходов на устранение недостатков, когда право заказчика устранять их предусмотрено в договоре подряда (статья 397).\n\n2. Подрядчик вправе вместо устранения недостатков, за которые он отвечает, безвозмездно выполнить работу заново с возмещением заказчику причиненных просрочкой исполнения убытков. В этом случае заказчик обязан возвратить ранее переданный ему результат работы подрядчику, если по характеру работы такой возврат возможен.\n\n3. Если отступления в работе от условий договора подряда или иные недостатки результата работы в установленный заказчиком разумный срок не были устранены либо являются существенными и неустранимыми, заказчик вправе отказаться от исполнения договора и потребовать возмещения причиненных убытков.\n\n4. Условие договора подряда об освобождении подрядчика от ответственности за определенные недостатки не освобождает его от ответственности, если доказано, что такие недостатки возникли вследствие виновных действий или бездействия подрядчика.\n\n5. Подрядчик, предоставивший материал для выполнения работы, отвечает за его качество по правилам об ответственности продавца за товары ненадлежащего качества (статья 475).","article_title":"Статья 723. Ответственность подрядчика за ненадлежащее качество работы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"14996c225d4ad27ee1ce76e98a3d9ca777404c027bb0f7ce9fcb749925835100"},{"code_id":"GK_RF_2","article_number":"724","version_date":"1994-11-30","article_text":"1. Если иное не установлено законом или договором подряда, заказчик вправе предъявить требования, связанные с ненадлежащим качеством результата работы, при условии, что оно выявлено в сроки, установленные настоящей статьей.\n\n2. В случае, когда на результат работы не установлен гарантийный срок, требования, связанные с недостатками результата работы, могут быть предъявлены заказчиком при условии, что они были обнаружены в разумный срок, но в пределах двух лет со дня передачи результата работы, если иные сроки не установлены законом, договором или обычаями делового оборота.\n\n3. Заказчик вправе предъявить требования, связанные с недостатками результата работы, обнаруженными в течение гарантийного срока.\n\n4. В случае, когда предусмотренный договором гарантийный срок составляет менее двух лет и недостатки результата работы обнаружены заказчиком по истечении гарантийного срока, но в пределах двух лет с момента, предусмотренного пунктом 5 настоящей статьи, подрядчик несет ответственность, если заказчик докажет, что недостатки возникли до передачи результата работы заказчику или по причинам, возникшим до этого момента.\n\n5. Если иное не предусмотрено договором подряда, гарантийный срок (пункт 1 статьи 722) начинает течь с момента, когда результат выполненной работы был принят или должен был быть принят заказчиком.\n\n6. К исчислению гарантийного срока по договору подряда применяются соответственно правила, содержащиеся в пунктах 2 и 4 статьи 471 настоящего Кодекса, если иное не предусмотрено законом, иными правовыми актами, соглашением сторон или не вытекает из особенностей договора подряда.","article_title":"Статья 724. Сроки обнаружения ненадлежащего качества результата работы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0822b7384b341f631e8d12270be57b360f3b9d85d33665ad11a98963faeaf7ab"},{"code_id":"GK_RF_2","article_number":"725","version_date":"1994-11-30","article_text":"1. Срок исковой давности для требований, предъявляемых в связи с ненадлежащим качеством работы, выполненной по договору подряда, составляет один год, а в отношении зданий и сооружений определяется по правилам статьи 196 настоящего Кодекса.\n\n2. Если в соответствии с договором подряда результат работы принят заказчиком по частям, течение срока исковой давности начинается со дня приемки результата работы в целом.\n\n3. Если законом, иными правовыми актами или договором подряда установлен гарантийный срок и заявление по поводу недостатков результата работы сделано в пределах гарантийного срока, течение срока исковой давности, указанного в пункте 1 настоящей статьи, начинается со дня заявления о недостатках.","article_title":"Статья 725. Давность по искам о ненадлежащем качестве работы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"46ab8ef6a1bd769615b756507f1364b203ec1344765f3ac0482d6e7eeec92783"},{"code_id":"GK_RF_2","article_number":"726","version_date":"1994-11-30","article_text":"Подрядчик обязан передать заказчику вместе с результатом работы информацию, касающуюся эксплуатации или иного использования предмета договора подряда, если это предусмотрено договором либо характер информации таков, что без нее невозможно использование результата работы для целей, указанных в договоре.","article_title":"Статья 726. Обязанность подрядчика передать информацию заказчику","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4c07375e5c5996e11ca93024a4babbe1d0ff41f1d974fecd605035049c944f42"},{"code_id":"GK_RF_2","article_number":"727","version_date":"1994-11-30","article_text":"Если сторона благодаря исполнению своего обязательства по договору подряда получила от другой стороны информацию о новых решениях и технических знаниях, в том числе не защищаемых законом, а также сведения, в отношении которых их обладателем установлен режим коммерческой тайны, сторона, получившая такую информацию, не вправе сообщать ее третьим лицам без согласия другой стороны. (В редакции Федерального закона от 12.03.2014 № 35-ФЗ)\n\nПорядок и условия пользования такой информацией определяются соглашением сторон.","article_title":"Статья 727. Конфиденциальность полученной сторонами информации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"15a886a5d3a0a1f5c455ad8131f422c094719404754282bf1fd7cfea635b2914"},{"code_id":"GK_RF_2","article_number":"728","version_date":"1994-11-30","article_text":"В случаях, когда заказчик на основании пункта 2 статьи 715 или пункта 3 статьи 723 настоящего Кодекса расторгает договор подряда, подрядчик обязан возвратить предоставленные заказчиком материалы, оборудование, переданную для переработки (обработки) вещь и иное имущество либо передать их указанному заказчиком лицу, а если это оказалось невозможным, - возместить стоимость материалов, оборудования и иного имущества.","article_title":"Статья 728. Возвращение подрядчиком имущества, переданного заказчиком","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4b3026e25a74cb82b72bdd3b6657e089c4a032bbd1d4c0f930404324eac17a34"},{"code_id":"GK_RF_2","article_number":"729","version_date":"1994-11-30","article_text":"В случае прекращения договора подряда по основаниям, предусмотренным законом или договором, до приемки заказчиком результата работы, выполненной подрядчиком (пункт 1 статьи 720), заказчик вправе требовать передачи ему результата незавершенной работы с компенсацией подрядчику произведенных затрат.","article_title":"Статья 729. Последствия прекращения договора подряда до приемки результата работы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a1c17ecf8a023865cfd2723eb32159f9109266e33c36b1abf49fb9cdb7c62542"},{"code_id":"GK_RF_2","article_number":"730","version_date":"1994-11-30","article_text":"1. По договору бытового подряда подрядчик, осуществляющий соответствующую предпринимательскую деятельность, обязуется выполнить по заданию гражданина (заказчика) определенную работу, предназначенную удовлетворять бытовые или другие личные потребности заказчика, а заказчик обязуется принять и оплатить работу.\n\n2. Договор бытового подряда является публичным договором (статья 426).\n\n3. К отношениям по договору бытового подряда, не урегулированным настоящим Кодексом, применяются законы о защите прав потребителей и иные правовые акты, принятые в соответствии с ними.","article_title":"Статья 730. Договор бытового подряда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b6befc543cb2cd051e02484d2c9ba6d7c950a2bc37e125e6c8463076893b382"},{"code_id":"GK_RF_2","article_number":"731","version_date":"1994-11-30","article_text":"1. Подрядчик не вправе навязывать заказчику включение в договор бытового подряда дополнительной работы или услуги. Заказчик вправе отказаться от оплаты работы или услуги, не предусмотренной договором.\n\n2. Заказчик вправе в любое время до сдачи ему работы отказаться от исполнения договора бытового подряда, уплатив подрядчику часть установленной цены пропорционально части работы, выполненной до уведомления об отказе от исполнения договора, и возместив подрядчику расходы, произведенные до этого момента в целях исполнения договора, если они не входят в указанную часть цены работы. Условия договора, лишающие заказчика этого права, ничтожны.","article_title":"Статья 731. Гарантии прав заказчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eb1935ec7444c9c3e5226bc755d2de351bb61f8e48033c8688c4cc4ef155c285"},{"code_id":"GK_RF_2","article_number":"732","version_date":"1994-11-30","article_text":"1. Подрядчик обязан до заключения договора бытового подряда предоставить заказчику необходимую и достоверную информацию о предлагаемой работе, ее видах и об особенностях, о цене и форме оплаты, а также сообщить заказчику по его просьбе другие относящиеся к договору и соответствующей работе сведения. Если по характеру работы это имеет значение, подрядчик должен указать заказчику конкретное лицо, которое будет ее выполнять.\n\n2. Если заказчику не предоставлена возможность незамедлительно получить в месте заключения договора бытового подряда информацию о работе, указанную в пункте 1 настоящей статьи, он вправе потребовать от подрядчика возмещения убытков, вызванных необоснованным уклонением от заключения договора (пункт 4 статьи 445).\n\nЗаказчик вправе требовать расторжения заключенного договора бытового подряда без оплаты выполненной работы, а также возмещения убытков в случаях, когда вследствие неполноты или недостоверности полученной\n\nот подрядчика информации был заключен договор на выполнение работы, не обладающей свойствами, которые имел в виду заказчик.\n\nПодрядчик, не предоставивший заказчику информации о работе, указанной в пункте 1 настоящей статьи, несет ответственность и за те недостатки работы, которые возникли после ее передачи заказчику вследствие отсутствия у него такой информации.\n\n(Пункт в редакции Федерального закона от 17.12.1999 № 213-ФЗ)","article_title":"Статья 732. Предоставление заказчику информации о предлагаемой работе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"741311e8168180d11fdc895d5735bec5b44aee203168dcdd0f410985f5feac0d"},{"code_id":"GK_RF_2","article_number":"733","version_date":"1994-11-30","article_text":"1. Если работа по договору бытового подряда выполняется из материала подрядчика, материал оплачивается заказчиком при заключении договора полностью или в части, указанной в договоре, с окончательным расчетом при получении заказчиком выполненной подрядчиком работы.\n\nВ соответствии с договором материал может быть предоставлен подрядчиком в кредит, в том числе с условием оплаты заказчиком материала в рассрочку.\n\n2. Изменение после заключения договора бытового подряда цены предоставленного подрядчиком материала не влечет перерасчета.","article_title":"Статья 733. Выполнение работы из материала подрядчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7f5fdc09e6b2ce5b45ea72ddfe5c1c3ed34cdbdaeee57ce96e87442d4b9586c0"},{"code_id":"GK_RF_2","article_number":"734","version_date":"1994-11-30","article_text":"Если работа по договору бытового подряда выполняется из материала заказчика, в квитанции или ином документе, выдаваемых подрядчиком заказчику при заключении договора, должны быть указаны точное наименование, описание и цена материала, определяемая по соглашению сторон. Оценка материала в квитанции или ином аналогичном документе может быть впоследствии оспорена заказчиком в суде.","article_title":"Статья 734. Выполнение работы из материала заказчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7b3324852c0f831cf7a79f934985ed4a5b727cf4e4cdb13c81f0b750b7a6f53b"},{"code_id":"GK_RF_2","article_number":"735","version_date":"1994-11-30","article_text":"Цена работы в договоре бытового подряда определяется соглашением сторон и не может быть выше устанавливаемой или регулируемой соответствующими государственными органами. Работа оплачивается заказчиком после ее окончательной сдачи подрядчиком. С согласия заказчика работа может быть оплачена им при заключении договора полностью или путем выдачи аванса.","article_title":"Статья 735. Цена и оплата работы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cfc4e3787944ff2d1830e1b597b1523f26d75581af5f54c340736055ce034b35"},{"code_id":"GK_RF_2","article_number":"736","version_date":"1994-11-30","article_text":"При сдаче работы заказчику подрядчик обязан сообщить ему о требованиях, которые необходимо соблюдать для эффективного и безопасного использования результата работы, а также о возможных для самого заказчика и других лиц последствиях несоблюдения соответствующих требований.","article_title":"Статья 736. Предупреждение заказчика об условиях использования выполненной работы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1395d1bc49b5deff55732b943b11b76c0a13d6f7a869f66ee36dbf6505fa125f"},{"code_id":"GK_RF_2","article_number":"738","version_date":"1994-11-30","article_text":"В случае неявки заказчика за получением результата выполненной работы или иного уклонения заказчика от его приемки подрядчик вправе, письменно предупредив заказчика, по истечении двух месяцев со дня такого предупреждения продать результат работы за разумную цену, а вырученную сумму, за вычетом всех причитающихся подрядчику платежей, внести в депозит в порядке, предусмотренном статьей 327 настоящего Кодекса.","article_title":"Статья 738. Последствия неявки заказчика за получением результата работы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e542ea6510c0bf46533b058296b62b81352fdbaecf4645bc8249a6c68656661a"},{"code_id":"GK_RF_2","article_number":"739","version_date":"1994-11-30","article_text":"В случае ненадлежащего выполнения или невыполнения работы по договору бытового подряда заказчик может воспользоваться правами, предоставленными покупателю в соответствии со статьями 503 - 505 настоящего Кодекса.","article_title":"Статья 739. Права заказчика в случае ненадлежащего выполнения или невыполнения работы по договору бытового подряда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f0da50302b2460e9153648b99cb5441d1948c95c3cb4804218d7e32bd73cb311"},{"code_id":"GK_RF_2","article_number":"740","version_date":"1994-11-30","article_text":"1. По договору строительного подряда подрядчик обязуется в установленный договором срок построить по заданию заказчика определенный объект либо выполнить иные строительные работы, а заказчик обязуется создать подрядчику необходимые условия для выполнения работ, принять их результат и уплатить обусловленную цену.\n\n2. Договор строительного подряда заключается на строительство или реконструкцию предприятия, здания (в том числе жилого дома), сооружения или иного объекта, а также на выполнение монтажных, пусконаладочных и иных неразрывно связанных со строящимся объектом работ. Правила о договоре строительного подряда применяются также к работам по капитальному ремонту зданий и сооружений, если иное не предусмотрено договором.\n\nВ случаях, предусмотренных договором, подрядчик принимает на себя обязанность обеспечить эксплуатацию объекта после его принятия заказчиком в течение указанного в договоре срока.\n\n3. В случаях, когда по договору строительного подряда выполняются работы для удовлетворения бытовых или других личных потребностей гражданина (заказчика), к такому договору соответственно применяются правила параграфа 2 настоящей главы о правах заказчика по договору бытового подряда.","article_title":"Статья 740. Договор строительного подряда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0393104ee95bc8b6e63776de2f9ed3d064479472d7f197c47e606c132777e56f"},{"code_id":"GK_RF_2","article_number":"741","version_date":"1994-11-30","article_text":"1. Риск случайной гибели или случайного повреждения объекта строительства, составляющего предмет договора строительного подряда, до приемки этого объекта заказчиком несет подрядчик.\n\n2. Если объект строительства до его приемки заказчиком погиб или поврежден вследствие недоброкачественности предоставленного заказчиком материала (деталей, конструкций) или оборудования либо исполнения ошибочных указаний заказчика, подрядчик вправе требовать оплаты всей предусмотренной сметой стоимости работ при условии, что им были выполнены обязанности, предусмотренные пунктом 1 статьи 716 настоящего Кодекса.","article_title":"Статья 741. Распределение риска между сторонами","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86e728462270d5651d17c8bd888765a7d98feefaf85ad368b32c66c7d81304b3"},{"code_id":"GK_RF_2","article_number":"742","version_date":"1994-11-30","article_text":"1. Договором строительного подряда может быть предусмотрена обязанность стороны, на которой лежит риск случайной гибели или случайного повреждения объекта строительства, материала, оборудования и другого имущества, используемых при строительстве, либо ответственность за причинение при осуществлении строительства вреда другим лицам, застраховать соответствующие риски.\n\nСторона, на которую возлагается обязанность по страхованию, должна предоставить другой стороне доказательства заключения ею договора страхования на условиях, предусмотренных договором строительного подряда, включая данные о страховщике, размере страховой суммы и застрахованных рисках.\n\n2. Страхование не освобождает соответствующую сторону от обязанности принять необходимые меры для предотвращения наступления страхового случая.","article_title":"Статья 742. Страхование объекта строительства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4ecfd585e803046638c33b71eb65080ef292b9aab8d8e69501e60a13d1c9e6e1"},{"code_id":"GK_RF_2","article_number":"743","version_date":"1994-11-30","article_text":"1. Подрядчик обязан осуществлять строительство и связанные с ним работы в соответствии с технической документацией, определяющей объем, содержание работ и другие предъявляемые к ним требования, и со сметой, определяющей цену работ.\n\nПри отсутствии иных указаний в договоре строительного подряда предполагается, что подрядчик обязан выполнить все работы, указанные в технической документации и в смете.\n\n2. Договором строительного подряда должны быть определены состав и содержание технической документации, а также должно быть предусмотрено, какая из сторон и в какой срок должна предоставить соответствующую документацию.\n\n3. Подрядчик, обнаруживший в ходе строительства не учтенные в технической документации работы и в связи с этим необходимость проведения дополнительных работ и увеличения сметной стоимости строительства, обязан сообщить об этом заказчику.\n\nПри неполучении от заказчика ответа на свое сообщение в течение десяти дней, если законом или договором строительного подряда не предусмотрен для этого иной срок, подрядчик обязан приостановить соответствующие работы с отнесением убытков, вызванных простоем, на счет заказчика. Заказчик освобождается от возмещения этих убытков, если докажет отсутствие необходимости в проведении дополнительных работ.\n\n4. Подрядчик, не выполнивший обязанности, установленной пунктом 3 настоящей статьи, лишается права требовать от заказчика оплаты выполненных им дополнительных работ и возмещения вызванных этим убытков, если не докажет необходимость немедленных действий в интересах заказчика, в частности в связи с тем, что приостановление работ могло привести к гибели или повреждению объекта строительства.\n\n5. При согласии заказчика на проведение и оплату дополнительных работ подрядчик вправе отказаться от их выполнения лишь в случаях, когда они не входят в сферу профессиональной деятельности подрядчика либо не могут быть выполнены подрядчиком по не зависящим от него причинам.","article_title":"Статья 743. Техническая документация и смета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e1a2466e188e708375c791a81ed32afd85ab5de6cdf239e286cd6fb45f8c8433"},{"code_id":"GK_RF_2","article_number":"744","version_date":"1994-11-30","article_text":"1. Заказчик вправе вносить изменения в техническую документацию при условии, если вызываемые этим дополнительные работы по стоимости не превышают десяти процентов указанной в смете общей стоимости строительства и не меняют характера предусмотренных в договоре строительного подряда работ.\n\n2. Внесение в техническую документацию изменений в большем против указанного в пункте 1 настоящей статьи объеме осуществляется на основе согласованной сторонами дополнительной сметы.\n\n3. Подрядчик вправе требовать в соответствии со статьей 450 настоящего Кодекса пересмотра сметы, если по не зависящим от него причинам стоимость работ превысила смету не менее чем на десять процентов.\n\n4. Подрядчик вправе требовать возмещения разумных расходов, которые понесены им в связи с установлением и устранением дефектов в технической документации.","article_title":"Статья 744. Внесение изменений в техническую документацию","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7e8591c652745ea85b6de23630c319981cbdd12d507b98b17f69c41da04626bb"},{"code_id":"GK_RF_2","article_number":"745","version_date":"1994-11-30","article_text":"1. Обязанность по обеспечению строительства материалами, в том числе деталями и конструкциями, или оборудованием несет подрядчик, если договором строительного подряда не предусмотрено, что обеспечение строительства в целом или в определенной части осуществляет заказчик.\n\n2. Сторона, в обязанность которой входит обеспечение строительства, несет ответственность за обнаружившуюся невозможность использования предоставленных ею материалов или оборудования без ухудшения качества выполняемых работ, если не докажет, что невозможность использования возникла по обстоятельствам, за которые отвечает другая сторона.\n\n3. В случае обнаружившейся невозможности использования предоставленных заказчиком материалов или оборудования без ухудшения качества выполняемых работ и отказа заказчика от их замены подрядчик вправе отказаться от договора строительного подряда и потребовать от заказчика уплаты цены договора пропорционально выполненной части работ.","article_title":"Статья 745. Обеспечение строительства материалами и оборудованием","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"306300183d5028644771f7f984dfb9f1d38ba2c9bb9b800329370a97c9194fdb"},{"code_id":"GK_RF_2","article_number":"746","version_date":"1994-11-30","article_text":"1. Оплата выполненных подрядчиком работ производится заказчиком в размере, предусмотренном сметой, в сроки и в порядке, которые установлены законом или договором строительного подряда. При отсутствии соответствующих указаний в законе или договоре оплата работ производится в соответствии со статьей 711 настоящего Кодекса.\n\n2. Договором строительного подряда может быть предусмотрена оплата работ единовременно и в полном объеме после приемки объекта заказчиком.","article_title":"Статья 746. Оплата работ","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4d82fb2dddc4c319574452b6ccb216c1903065d34907b802422c22ac641af5ff"},{"code_id":"GK_RF_2","article_number":"747","version_date":"1994-11-30","article_text":"1. Заказчик обязан своевременно предоставить для строительства земельный участок. Площадь и состояние предоставляемого земельного участка должны соответствовать содержащимся в договоре строительного подряда условиям, а при отсутствии таких условий обеспечивать своевременное начало работ, нормальное их ведение и завершение в срок.\n\n2. Заказчик обязан в случаях и в порядке, предусмотренных договором строительного подряда, передавать подрядчику в пользование необходимые для осуществления работ здания и сооружения, обеспечивать транспортировку грузов в его адрес, временную подводку сетей энергоснабжения, водо- и паропровода и оказывать другие услуги.\n\n3. Оплата предоставленных заказчиком услуг, указанных в пункте 2 настоящей статьи, осуществляется в случаях и на условиях, предусмотренных договором строительного подряда.","article_title":"Статья 747. Дополнительные обязанности заказчика по договору строительного подряда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f9784b6ea38c31a3f3e7076c50cb2b48f6319db7dfe1a507e2619456f0613475"},{"code_id":"GK_RF_2","article_number":"748","version_date":"1994-11-30","article_text":"1. Заказчик вправе осуществлять контроль и надзор за ходом и качеством выполняемых работ, соблюдением сроков их выполнения (графика), качеством предоставленных подрядчиком материалов, а также правильностью использования подрядчиком материалов заказчика, не вмешиваясь при этом в оперативно-хозяйственную деятельность подрядчика.\n\n2. Заказчик, обнаруживший при осуществлении контроля и надзора за выполнением работ отступления от условий договора строительного подряда, которые могут ухудшить качество работ, или иные их недостатки, обязан немедленно заявить об этом подрядчику. Заказчик, не сделавший такого заявления, теряет право в дальнейшем ссылаться на обнаруженные им недостатки.\n\n3. Подрядчик обязан исполнять полученные в ходе строительства указания заказчика, если такие указания не противоречат условиям договора строительного подряда и не представляют собой вмешательство в оперативно-хозяйственную деятельность подрядчика.\n\n4. Подрядчик, ненадлежащим образом выполнивший работы, не вправе ссылаться на то, что заказчик не осуществлял контроль и надзор за их выполнением, кроме случаев, когда обязанность осуществлять такой контроль и надзор возложена на заказчика законом.","article_title":"Статья 748. Контроль и надзор заказчика за выполнением работ по договору строительного подряда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d06eff53c482f20a4e6ab6f1e321a8e3bf151720ef6d0fafe9d8ce1c7072f552"},{"code_id":"GK_RF_2","article_number":"749","version_date":"1994-11-30","article_text":"Заказчик в целях осуществления контроля и надзора за строительством и принятия от его имени решений во взаимоотношениях с подрядчиком может заключить самостоятельно без согласия подрядчика договор об оказании заказчику услуг такого рода с соответствующим инженером (инженерной организацией). В этом случае в договоре строительного подряда определяются функции такого инженера (инженерной организации), связанные с последствиями его действий для подрядчика.","article_title":"Статья 749. Участие инженера (инженерной организации) в осуществлении прав и выполнении обязанностей заказчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dc146ca29287a0db6fef8632b8fa511d4a0a27af9d57e8ee06219a0e8092ba37"},{"code_id":"GK_RF_2","article_number":"750","version_date":"1994-11-30","article_text":"1. Если при выполнении строительства и связанных с ним работ обнаруживаются препятствия к надлежащему исполнению договора строительного подряда, каждая из сторон обязана принять все зависящие от нее разумные меры по устранению таких препятствий. Сторона, не исполнившая этой обязанности, утрачивает право на возмещение убытков, причиненных тем, что соответствующие препятствия не были устранены.\n\n2. Расходы стороны, связанные с исполнением обязанностей, указанных в пункте 1 настоящей статьи, подлежат возмещению другой стороной в случаях, когда это предусмотрено договором строительного подряда.","article_title":"Статья 750. Сотрудничество сторон в договоре строительного подряда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ffd9743b64d87ff15c62a0fe26f5c0d441cbefbd321acead546520a25f7f1eaa"},{"code_id":"GK_RF_2","article_number":"751","version_date":"1994-11-30","article_text":"1. Подрядчик обязан при осуществлении строительства и связанных с ним работ соблюдать требования закона и иных правовых актов об охране окружающей среды и о безопасности строительных работ.\n\nПодрядчик несет ответственность за нарушение указанных требований.\n\n2. Подрядчик не вправе использовать в ходе осуществления работ материалы и оборудование, предоставленные заказчиком, или выполнять его указания, если это может привести к нарушению обязательных для сторон требований к охране окружающей среды и безопасности строительных работ.","article_title":"Статья 751. Обязанности подрядчика по охране окружающей среды и обеспечению безопасности строительных работ","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"513cfc55919b65b0337e942f5834c93776fb65c1c446de41fcd15efe82fc996d"},{"code_id":"GK_RF_2","article_number":"752","version_date":"1994-11-30","article_text":"Если по не зависящим от сторон причинам работы по договору строительного подряда приостановлены и объект строительства законсервирован, заказчик обязан оплатить подрядчику в полном объеме выполненные до момента консервации работы, а также возместить расходы, вызванные необходимостью прекращения работ и консервацией строительства, с зачетом выгод, которые подрядчик получил или мог получить вследствие прекращения работ.","article_title":"Статья 752. Последствия консервации строительства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8c28a0ed4cbb619f96f4d5636626d4a82ae127d152177443ddda2a0240d9ffaf"},{"code_id":"GK_RF_2","article_number":"753","version_date":"1994-11-30","article_text":"1. Заказчик, получивший сообщение подрядчика о готовности к сдаче результата выполненных по договору строительного подряда работ либо, если это предусмотрено договором, выполненного этапа работ, обязан немедленно приступить к его приемке.\n\n2. Заказчик организует и осуществляет приемку результата работ за свой счет, если иное не предусмотрено договором строительного подряда.\n\nВ предусмотренных законом или иными правовыми актами случаях в приемке результата работ должны участвовать представители государственных органов и органов местного самоуправления.\n\n3. Заказчик, предварительно принявший результат отдельного этапа работ, несет риск последствий гибели или повреждения результата работ, которые произошли не по вине подрядчика.\n\n4. Сдача результата работ подрядчиком и приемка его заказчиком оформляются актом, подписанным обеими сторонами. При отказе одной из сторон от подписания акта в нем делается отметка об этом и акт подписывается другой стороной.\n\nОдносторонний акт сдачи или приемки результата работ может быть признан судом недействительным лишь в случае, если мотивы отказа от подписания акта признаны им обоснованными.\n\n5. В случаях, когда это предусмотрено законом или договором строительного подряда либо вытекает из характера работ, выполняемых по договору, приемке результата работ должны предшествовать предварительные испытания. В этих случаях приемка может осуществляться только при положительном результате предварительных испытаний.\n\n6. Заказчик вправе отказаться от приемки результата работ в случае обнаружения недостатков, которые исключают возможность его использования для указанной в договоре строительного подряда цели и не могут быть устранены подрядчиком или заказчиком.","article_title":"Статья 753. Сдача и приемка работ","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b398d9b361df2651f55b49f8d7d8d675e93ea13e10c9a81497099e4156a68277"},{"code_id":"GK_RF_2","article_number":"754","version_date":"1994-11-30","article_text":"1. Подрядчик несет ответственность перед заказчиком за допущенные отступления от требований, предусмотренных в технической документации и в обязательных для сторон строительных нормах и правилах, а также за недостижение указанных в технической документации показателей объекта строительства, в том числе таких, как производственная мощность предприятия.\n\nПри реконструкции (обновлении, перестройке, реставрации и т.п.) здания или сооружения на подрядчика возлагается ответственность за снижение или потерю прочности, устойчивости, надежности здания, сооружения или его части.\n\n2. Подрядчик не несет ответственности за допущенные им без согласия заказчика мелкие отступления от технической документации, если докажет, что они не повлияли на качество объекта строительства.","article_title":"Статья 754. Ответственность подрядчика за качество работ","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cbb1d2851622ca28218f41977149dd5621e13fe9aa0882864f5f32b5b9fab245"},{"code_id":"GK_RF_2","article_number":"755","version_date":"1994-11-30","article_text":"1. Подрядчик, если иное не\n\nпредусмотрено договором строительного подряда, гарантирует достижение объектом строительства указанных в технической документации показателей и возможность эксплуатации объекта в соответствии с договором строительного подряда на протяжении гарантийного срока. Установленный законом гарантийный срок может быть увеличен соглашением сторон.\n\n2. Подрядчик несет ответственность за недостатки (дефекты), обнаруженные в пределах гарантийного срока, если не докажет, что они произошли вследствие нормального износа объекта или его частей, неправильной его эксплуатации или неправильности инструкций по его эксплуатации, разработанных самим заказчиком или привлеченными им третьими лицами, ненадлежащего ремонта объекта, произведенного самим заказчиком или привлеченными им третьими лицами.\n\n3. Течение гарантийного срока прерывается на все время, на протяжении которого объект не мог эксплуатироваться вследствие недостатков, за которые отвечает подрядчик.\n\n4. При обнаружении в течение гарантийного срока недостатков, указанных в пункте 1 статьи 754 настоящего Кодекса, заказчик должен заявить о них подрядчику в разумный срок по их обнаружении.","article_title":"Статья 755. Гарантии качества в договоре строительного подряда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"88739a77e1121fa5ecd970970cc6cd1ce9e51b8308855059f07748c460391223"},{"code_id":"GK_RF_2","article_number":"756","version_date":"1994-11-30","article_text":"При предъявлении требований, связанных с ненадлежащим качеством результата работ, применяются правила, предусмотренные пунктами 1 - 5 статьи 724 настоящего Кодекса.\n\nПри этом предельный срок обнаружения недостатков, в соответствии с пунктами 2 и 4 статьи 724 настоящего Кодекса, составляет пять лет.","article_title":"Статья 756. Сроки обнаружения ненадлежащего качества строительных работ","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e9705f63d2dac8facf9b05de6c237f5f94c15f2174b2615be5374833a0360c41"},{"code_id":"GK_RF_2","article_number":"757","version_date":"1994-11-30","article_text":"1. Договором строительного подряда может быть предусмотрена обязанность подрядчика устранять по требованию заказчика и за его счет недостатки, за которые подрядчик не несет ответственности.\n\n2. Подрядчик вправе отказаться от выполнения обязанности, указанной в пункте 1 настоящей статьи, в случаях, когда устранение недостатков не связано непосредственно с предметом договора либо не может быть осуществлено подрядчиком по не зависящим от него причинам.","article_title":"Статья 757. Устранение недостатков за счет заказчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da2906cf1a6c7bef919d8061a1f402f46a1f6a3bb8b1d4be51c1ab7ffaa56828"},{"code_id":"GK_RF_2","article_number":"758","version_date":"1994-11-30","article_text":"По договору подряда на выполнение проектных и изыскательских работ подрядчик (проектировщик, изыскатель) обязуется по заданию заказчика разработать техническую документацию и (или) выполнить изыскательские работы, а заказчик обязуется принять и оплатить их результат.","article_title":"Статья 758. Договор подряда на выполнение проектных и изыскательских работ","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f32c914a94d85c2b8277b3ed74d4fc8a841e59f446e19480278cf70985599fe5"},{"code_id":"GK_RF_2","article_number":"759","version_date":"1994-11-30","article_text":"1. По договору подряда на выполнение проектных и изыскательских работ заказчик обязан передать подрядчику задание на проектирование, а также иные исходные данные, необходимые для составления технической документации. Задание на выполнение проектных работ может быть по поручению заказчика подготовлено подрядчиком. В этом случае задание становится обязательным для сторон с момента его утверждения заказчиком.\n\n2. Подрядчик обязан соблюдать требования, содержащиеся в задании и других исходных данных для выполнения проектных и изыскательских работ, и вправе отступить от них только с согласия заказчика.","article_title":"Статья 759. Исходные данные для выполнения проектных и изыскательских работ","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a36c36ad44ecfb0703baad3399da8920741c1f68277144eeef8e4257626a451c"},{"code_id":"GK_RF_2","article_number":"760","version_date":"1994-11-30","article_text":"1. По договору подряда на выполнение проектных и изыскательских работ подрядчик обязан:\n\nвыполнять работы в соответствии с заданием и иными исходными данными на проектирование и договором;\n\nсогласовывать готовую техническую документацию с заказчиком, а при необходимости вместе с заказчиком - с компетентными государственными органами и органами местного самоуправления;\n\nпередать заказчику готовую техническую документацию и результаты изыскательских работ.\n\nПодрядчик не вправе передавать техническую документацию третьим лицам без согласия заказчика.\n\n2. Подрядчик по договору подряда на выполнение проектных и изыскательских работ гарантирует заказчику отсутствие у третьих лиц права воспрепятствовать выполнению работ или ограничивать их выполнение на основе подготовленной подрядчиком технической документации.","article_title":"Статья 760. Обязанности подрядчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6307d03ad592cdb91b0f31dc1e0483683f540a3223adc9b37082f16fb4a0669"},{"code_id":"GK_RF_2","article_number":"761","version_date":"1994-11-30","article_text":"1. Подрядчик по договору подряда на выполнение проектных и изыскательских работ несет ответственность за ненадлежащее составление технической документации и выполнение изыскательских работ, включая недостатки, обнаруженные впоследствии в ходе строительства, а также в процессе эксплуатации объекта, созданного на основе технической документации и данных изыскательских работ.\n\n2. При обнаружении недостатков в технической документации или в изыскательских работах подрядчик по требованию заказчика обязан безвозмездно переделать техническую документацию и соответственно произвести необходимые дополнительные изыскательские работы, а также возместить заказчику причиненные убытки, если законом или договором подряда на выполнение проектных и изыскательских работ не установлено иное.","article_title":"Статья 761. Ответственность подрядчика за ненадлежащее выполнение проектных и изыскательских работ","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"531f462933c5cde5f4fc14fb07bf93997f1f8002250627d35ae7805508e213ed"},{"code_id":"GK_RF_2","article_number":"762","version_date":"1994-11-30","article_text":"По договору подряда на выполнение проектных и изыскательских работ заказчик обязан, если иное не предусмотрено договором:\n\nуплатить подрядчику установленную цену полностью после завершения всех работ или уплачивать ее частями после завершения отдельных этапов работ;\n\nиспользовать техническую документацию, полученную от подрядчика, только на цели, предусмотренные договором, не передавать техническую документацию третьим лицам и не разглашать содержащиеся в ней данные без согласия подрядчика;\n\nоказывать содействие подрядчику в выполнении проектных и изыскательских работ в объеме и на условиях, предусмотренных в договоре;\n\nучаствовать вместе с подрядчиком в согласовании готовой технической документации с соответствующими государственными органами и органами местного самоуправления;\n\nвозместить подрядчику дополнительные расходы, вызванные изменением исходных данных для выполнения проектных и изыскательских работ вследствие обстоятельств, не зависящих от подрядчика;\n\nпривлечь подрядчика к участию в деле по иску, предъявленному к заказчику третьим лицом в связи с недостатками составленной технической документации или выполненных изыскательских работ.\n\n(Наименование в редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 762. Обязанности заказчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d5f9ddabd7d3a3da3812a9c156e5edfcbb0d138968d979417dbbcc668896dd1e"},{"code_id":"GK_RF_2","article_number":"763","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 763. Государственный или муниципальный контракт на выполнение подрядных работ для государственных или муниципальных нужд","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5cb468ea27c85aa81dd33aa6ad038a21d6f28d31c86f04c651bb93ff60e9de89"},{"code_id":"GK_RF_2","article_number":"764","version_date":"1994-11-30","article_text":"1. По государственному или муниципальному контракту подрядчиком может выступать юридическое или физическое лицо.\n\n(Статья в редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 764. Стороны государственного или муниципального контракта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6cbf01f3b917345285b5430deaed8c22b5be95a2ec0cdeef6d730bed2e351609"},{"code_id":"GK_RF_2","article_number":"765","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 02.02.2006 № 19-ФЗ)\n\nОснования и порядок заключения государственного или муниципального контракта определяются в соответствии с положениями статей 527 и 528 настоящего Кодекса. (В редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 765. Основания и порядок заключения государственного или муниципального контракта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8e7087246aafc8f9408e9337b531c3cb1fd643a8f82b5d649222561337b0cd23"},{"code_id":"GK_RF_2","article_number":"766","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 766. Содержание государственного или муниципального контракта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"363e2ab0d32cfd18966e70b6f5e4a4132d2b4a8a42e993ac043313cd784a811e"},{"code_id":"GK_RF_2","article_number":"767","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 767. Изменение государственного или муниципального контракта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5cb468ea27c85aa81dd33aa6ad038a21d6f28d31c86f04c651bb93ff60e9de89"},{"code_id":"GK_RF_2","article_number":"768","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 02.02.2006 № 19-ФЗ)\n\nК отношениям по государственным или муниципальным контрактам на выполнение подрядных работ для государственных или муниципальных нужд в части, не урегулированной настоящим Кодексом, применяется закон о подрядах для государственных или муниципальных нужд. (В редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 768. Правовое регулирование государственного или муниципального контракта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ddb56e68ecb01438cc8140568aa36f0acdc817084985348a60f513b79fe6457e"},{"code_id":"GK_RF_2","article_number":"770","version_date":"1994-11-30","article_text":"1. Исполнитель обязан провести научные исследования лично. Он вправе привлекать к исполнению договора на выполнение научно-исследовательских работ третьих лиц только с согласия заказчика.\n\n2. При выполнении опытно-конструкторских или технологических работ исполнитель вправе, если иное не предусмотрено договором, привлекать к его исполнению третьих лиц. К отношениям исполнителя с третьими лицами применяются правила о генеральном подрядчике и субподрядчике (статья 706).","article_title":"Статья 770. Выполнение работ","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3f2de62085fdbfb9dca1ba1e93142716e2969732f74a22d61aead1afc65266fa"},{"code_id":"GK_RF_2","article_number":"771","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договорами на выполнение научно-исследовательских работ, опытно-конструкторских и технологических работ, стороны обязаны обеспечить конфиденциальность сведений, касающихся предмета договора, хода его исполнения и полученных результатов. Объем сведений, признаваемых конфиденциальными, определяется в договоре.\n\n2. Каждая из сторон обязуется публиковать полученные при выполнении работы сведения, признанные конфиденциальными, только с согласия другой стороны.","article_title":"Статья 771. Конфиденциальность сведений, составляющих предмет договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"728bbe0f2669e8b4f228efca393b55092850c3e2f5805f6bccd86b20429e603f"},{"code_id":"GK_RF_2","article_number":"773","version_date":"1994-11-30","article_text":"Исполнитель в договорах на выполнение научно-исследовательских работ, опытно-конструкторских и технологических работ обязан:\n\nвыполнить работы в соответствии с согласованным с заказчиком техническим заданием и передать заказчику их результаты в предусмотренный договором срок;\n\nсогласовать с заказчиком необходимость использования охраняемых результатов интеллектуальной деятельности, принадлежащих третьим лицам, и приобретение прав на их использование;\n\nсвоими силами и за свой счет устранять допущенные по его вине в выполненных работах недостатки, которые могут повлечь отступления от технико-экономических параметров, предусмотренных в техническом задании или в договоре;\n\nнезамедлительно информировать заказчика об обнаруженной невозможности получить ожидаемые результаты или о нецелесообразности продолжения работы;\n\nгарантировать заказчику передачу полученных по договору результатов, не нарушающих исключительных прав других лиц.","article_title":"Статья 773. Обязанности исполнителя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a53f156d3a98fd9be45eb0df598e54fccf2c947165fe07a4b17b175d6f7eaf22"},{"code_id":"GK_RF_2","article_number":"774","version_date":"1994-11-30","article_text":"1. Заказчик в договорах на выполнение научно-исследовательских работ, опытно-конструкторских и технологических работ обязан:\n\nпередавать исполнителю необходимую для выполнения работы информацию;\n\nпринять результаты выполненных работ и оплатить их.\n\n2. Договором может быть также предусмотрена обязанность заказчика выдать исполнителю техническое задание и согласовать с ним программу (технико-экономические параметры) или тематику работ.","article_title":"Статья 774. Обязанности заказчика","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5a50a4fb79b3f3ad30435be8498a799d40bd37558c67693f02ed35a7596ec390"},{"code_id":"GK_RF_2","article_number":"775","version_date":"1994-11-30","article_text":"Если в ходе научно-исследовательских работ обнаруживается невозможность достижения результатов вследствие обстоятельств, не зависящих от исполнителя, заказчик обязан оплатить стоимость работ, проведенных до выявления невозможности получить предусмотренные договором на выполнение научно-исследовательских работ результаты, но не свыше соответствующей части цены работ, указанной в договоре.","article_title":"Статья 775. Последствия невозможности достижения результатов научно-исследовательских работ","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"17fe0846b8a945dbc5880c2761698ca88eea10c9497fd1e40dfb92630c20a90f"},{"code_id":"GK_RF_2","article_number":"776","version_date":"1994-11-30","article_text":"Если в ходе выполнения опытно-конструкторских и технологических работ обнаруживается возникшая не по вине исполнителя невозможность или нецелесообразность продолжения работ, заказчик обязан оплатить понесенные исполнителем затраты.","article_title":"Статья 776. Последствия невозможности продолжения опытно-конструкторских и технологических работ","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cd7dc1c0d40a4180e948ebc22c029611d4056e1c772615496ee48eabeeb735db"},{"code_id":"GK_RF_2","article_number":"777","version_date":"1994-11-30","article_text":"1. Исполнитель несет ответственность перед заказчиком за нарушение договоров на выполнение научно-исследовательских работ, опытно-конструкторских и технологических работ, если не докажет, что такое нарушение произошло не по вине исполнителя (пункт 1 статьи 401).\n\n2. Исполнитель обязан возместить убытки, причиненные им заказчику, в пределах стоимости работ, в которых выявлены недостатки, если договором предусмотрено, что они подлежат возмещению в пределах общей стоимости работ по договору. Упущенная выгода подлежит возмещению в случаях, предусмотренных договором.","article_title":"Статья 777. Ответственность исполнителя за нарушение договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"68352a8f8f1f3d4029582f21de8572c3948ce257415cb8d3c4eebe4d947ce3c4"},{"code_id":"GK_RF_2","article_number":"778","version_date":"1994-11-30","article_text":"К договорам на выполнение научно-исследовательских, опытно-конструкторских и технологических работ применяются положения параграфа 1 главы 37 настоящего Кодекса, если это не противоречит правилам настоящей главы, а также особенностям предмета договоров на выполнение научно-исследовательских, опытно-конструкторских и технологических работ. К последствиям неявки заказчика за получением результатов таких работ применяются правила статьи 738 настоящего Кодекса. (В редакции Федерального закона от 22.12.2020 № 456-ФЗ)\n\nК государственным или муниципальным контрактам на выполнение научно-исследовательских работ, опытно-конструкторских и технологических работ для государственных или муниципальных нужд применяются правила статей 763 - 768 настоящего Кодекса. (В редакции Федерального закона от 02.02.2006 № 19-ФЗ)","article_title":"Статья 778. Правовое регулирование договоров на выполнение научно-исследовательских работ, опытно-конструкторских и технологических работ","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2ad31b1e29c0ca5e05c03c50dce0056258381744516a2314bf5d333373d7d594"},{"code_id":"GK_RF_2","article_number":"779","version_date":"1994-11-30","article_text":"1. По договору возмездного оказания услуг исполнитель обязуется по заданию заказчика оказать услуги (совершить определенные действия или осуществить определенную деятельность), а заказчик обязуется оплатить эти услуги.\n\n2. Правила настоящей главы применяются к договорам оказания услуг связи, медицинских, ветеринарных, аудиторских, консультационных, информационных услуг, услуг по обучению, туристическому обслуживанию и иных, за исключением услуг, оказываемых по договорам, предусмотренным главами 37, 38, 40, 41, 44, 45, 46, 47, 49, 51, 53 настоящего Кодекса.","article_title":"Статья 779. Договор возмездного оказания услуг","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"626ddb927de712baa1e1f1ac61505f3625cad0330671269477d29cde9d57b7ee"},{"code_id":"GK_RF_2","article_number":"780","version_date":"1994-11-30","article_text":"и иное не предусмотрено договором возмездного оказания услуг, исполнитель обязан оказать услуги лично.","article_title":"Статья 780. Исполнение договора возмездного оказания услуг","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"82824a6fda8b30d5a803efe463fc4d1bc72cfea0d7ee404ef006deb214a668c1"},{"code_id":"GK_RF_2","article_number":"781","version_date":"1994-11-30","article_text":"1. Заказчик обязан оплатить оказанные ему услуги в сроки и в порядке, которые указаны в договоре возмездного оказания услуг.\n\n2. В случае невозможности исполнения, возникшей по вине заказчика, услуги подлежат оплате в полном объеме, если иное не предусмотрено законом или договором возмездного оказания услуг.\n\n3. В случае, когда невозможность исполнения возникла по обстоятельствам, за которые ни одна из сторон не отвечает, заказчик возмещает исполнителю фактически понесенные им расходы, если иное не предусмотрено законом или договором возмездного оказания услуг.","article_title":"Статья 781. Оплата услуг","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3199d95be77de13709f814b6320967b02aeb415590631c4a87b5e9ad17be49cb"},{"code_id":"GK_RF_2","article_number":"782","version_date":"1994-11-30","article_text":"1. Заказчик вправе отказаться от исполнения договора возмездного оказания услуг при условии оплаты исполнителю фактически понесенных им расходов.\n\n2. Исполнитель вправе отказаться от исполнения обязательств по договору возмездного оказания услуг лишь при условии полного возмещения заказчику убытков.","article_title":"Статья 782. Односторонний отказ от исполнения договора возмездного оказания услуг","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a6df773eff867f743eaf33a161cc93e07871ffa16542df838720360799148583"},{"code_id":"GK_RF_2","article_number":"783","version_date":"1994-11-30","article_text":"Общие положения о подряде (статьи 702 - 729) и положения о бытовом подряде (статьи 730 - 739) применяются к договору возмездного оказания услуг, если это не противоречит статьям 779 - 782 настоящего Кодекса, а также особенностям предмета договора возмездного оказания услуг.","article_title":"Статья 783. Правовое регулирование договора возмездного оказания услуг","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b42fe25224eb231a6dc16529560de4248be0494489bf9f1cfddd087db0d84ecf"},{"code_id":"GK_RF_2","article_number":"783.1","version_date":"1994-11-30","article_text":"Договором, в силу которого исполнитель обязуется совершить действия по предоставлению определенной информации заказчику (договор об оказании услуг по предоставлению информации), может быть предусмотрена обязанность одной из сторон или обеих сторон не совершать в течение определенного периода действий, в результате которых информация может быть раскрыта третьим лицам.\n\n(Дополнение статьей - Федеральный закон от 18.03.2019 № 34-ФЗ)","article_title":"Статья 783.1. Особенности договора об оказании услуг по предоставлению информации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f769bc073c619a7f81f452f72ac50ffa4d92c86ca59ef0b0799d0dca083c20e6"},{"code_id":"GK_RF_2","article_number":"784","version_date":"1994-11-30","article_text":"1. Перевозка грузов, пассажиров и багажа осуществляется на основании договора перевозки.\n\n2. Общие условия перевозки определяются транспортными уставами и кодексами, иными законами и издаваемыми в соответствии с ними правилами.\n\nУсловия перевозки грузов, пассажиров и багажа отдельными видами транспорта, а также ответственность сторон по этим перевозкам определяются соглашением сторон, если настоящим Кодексом, транспортными уставами и кодексами, иными законами и издаваемыми в соответствии с ними правилами не установлено иное.","article_title":"Статья 784. Общие положения о перевозке","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3524ca17589a4dc20b7855f7d29456241bb0e46fd8e0450ab05476889b80d6c0"},{"code_id":"GK_RF_2","article_number":"785","version_date":"1994-11-30","article_text":"1. По договору перевозки груза перевозчик обязуется доставить вверенный ему отправителем груз в пункт назначения и выдать его управомоченному на получение груза лицу (получателю), а отправитель обязуется уплатить за перевозку груза установленную плату.\n\n2. Заключение договора перевозки груза подтверждается составлением и выдачей отправителю груза транспортной накладной (коносамента или иного документа на груз, предусмотренного соответствующим транспортным уставом или кодексом).","article_title":"Статья 785. Договор перевозки груза","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1168ee6b4e811621c700d74d6f4d0db841feb23309c8e2af6e120453c8fda748"},{"code_id":"GK_RF_2","article_number":"786","version_date":"1994-11-30","article_text":"1. По договору перевозки пассажира перевозчик обязуется перевезти пассажира в пункт назначения, а в случае сдачи пассажиром багажа также доставить багаж в пункт назначения и выдать его управомоченному на получение багажа лицу; пассажир обязуется уплатить установленную плату за проезд, а при сдаче багажа и за провоз багажа.\n\n2. Заключение договора перевозки пассажира удостоверяется билетом, а сдача пассажиром багажа багажной квитанцией.\n\nФормы билета и багажной квитанции устанавливаются в порядке, предусмотренном транспортными уставами, кодексами и иными законами. (В редакции Федерального закона от 29.12.2017 № 442-ФЗ)\n\nперевозить с собой детей бесплатно или на иных льготных условиях;\n\nпровозить с собой бесплатно ручную кладь в пределах установленных норм;\n\nсдавать к перевозке багаж за плату по тарифу.","article_title":"Статья 786. Договор перевозки пассажира","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a5d49a678f384ad73e6dd0d1a0abe7b6493ddcac5b6a5cb14fd17b073b3d53de"}]$law7v015$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
